const fs = require('node:fs');
const V = (m) => { console.error('DEVGOV_POSTPROVEN_HARDENING_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('DEVGOV_POSTPROVEN_HARDENING_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const required = ['scripts/devgov/invariant-packs.mjs','scripts/audit/devgovInvariantPacks.test.ts','.github/workflows/devgov-v0-gate.yml','.github/workflows/devgov-invariant-packs.yml','docs/architecture/audits/DEVGOV-INVARIANT-PACKS-V1-PROVEN.md'];
  for (const p of required) if (!fs.existsSync(p)) H('Step-5 positive-control path missing: ' + p);
  const runner = fs.readFileSync('scripts/devgov/invariant-packs.mjs','utf8');
  const tests = fs.readFileSync('scripts/audit/devgovInvariantPacks.test.ts','utf8');
  const gate = fs.readFileSync('.github/workflows/devgov-v0-gate.yml','utf8');
  const guards = [
    ['canonical containment', runner.includes('function resolveContainedPath(root, rel)')],
    ['safe pack path', runner.includes('function isSafePackPath(value)')],
    ['default branch binding', runner.includes("'test \"$BASE_REF\" = \"$DEFAULT_BRANCH\"'")],
    ['pack report reverify step', gate.includes('Reverify invariant-pack report binding')],
    ['pack outcome binding', gate.includes('PACKS_OUTCOME: ${{ steps.invariant_packs.outcome }}')],
    ['pack_ok final gate', gate.includes('test "$pack_ok" = true')],
    ['F04 regression', tests.includes('canonical pack verification becomes continue-on-error')],
    ['F05 regression', tests.includes('decoy plus dynamic candidate execution')],
    ['F06 regression', tests.includes('protected-default-base assertion')],
    ['F08 regression', tests.includes('report re-verification is reduced to a decoy comment')],
    ['F13 regression', tests.includes('prefix-valid pack path traversal')],
    ['F14 regression', tests.includes('caller non-impact metadata')],
  ];
  const missing = guards.filter(([, ok]) => !ok).map(([name]) => name);
  if (missing.length) V('post-PROVEN hardening guards missing: ' + missing.join(' | '));
  console.log('DEVGOV_POSTPROVEN_HARDENING_OK: all declared guards present');
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

